package com.fasterxml.jackson.databind.util;

import com.fasterxml.jackson.core.io.NumberInput;
import java.io.*;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.math.*;
import java.text.DateFormat;
import java.text.FieldPosition;
import java.text.ParseException;
import java.text.ParsePosition;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.Date;
import java.util.Locale;
import java.util.TimeZone;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

public class StdDateFormat__clearFormats_TriageGen2Test {

    @Test
    public void test_clearFormats_clearsInternalFormatters() throws Exception {
        // Arrange
        StdDateFormat dateFormat = new StdDateFormat();

        // We need to trigger the creation of the internal formatters before we can test if they are cleared.
        // Since they are private/protected fields, we use a date string to force Jackson to initialize them.
        String isoDate = "2023-10-27T10:00:00Z";
        String rfcDate = "Fri, 27 Oct 2023 10:00:00 GMT";

        dateFormat.parse(isoDate);
        dateFormat.parse(rfcDate);

        // Verify that the fields are NOT null after parsing (they should have been initialized)
        assertNotNull("RFC1123 format should be initialized", getField(dateFormat, "_formatRFC1123"));
        assertNotNull("ISO8601 format should be initialized", getField(dateFormat, "_formatISO8601"));
        assertNotNull("ISO8601_z format should be initialized", getField(dateFormat, "_formatISO8601_z"));
        assertNotNull("Plain format should be initialized", getField(dateFormat, "_formatPlain"));

        // Act
        // _clearFormats is protected, so we use reflection to invoke it
        Method clearFormatsMethod = StdDateFormat.class.getDeclaredMethod("_clearFormats");
        clearFormatsMethod.setAccessible(true);
        clearFormatsMethod.invoke(dateFormat);

        // Assert
        assertNull("RFC1123 format should be null after _clearFormats()", getField(dateFormat, "_formatRFC1123"));
        assertNull("ISO8601 format should be null after _clearFormats()", getField(dateFormat, "_formatISO8601"));
        assertNull("ISO8601_z format should be null after _clearFormats()", getField(dateFormat, "_formatISO8601_z"));
        assertNull("Plain format should be null after _clearFormats()", getField(dateFormat, "_formatPlain"));
    }

    @Test
    public void test_clearFormats_onNewInstance() throws Exception {
        // Arrange
        StdDateFormat dateFormat = new StdDateFormat(TimeZone.getDefault(), Locale.US);

        // Act
        Method clearFormatsMethod = StdDateFormat.class.getDeclaredMethod("_clearFormats");
        clearFormatsMethod.setAccessible(true);
        clearFormatsMethod.invoke(dateFormat);

        // Assert
        // On a fresh instance, these should already be null, and calling clear should keep them null
        assertNull(getField(dateFormat, "_formatRFC1123"));
        assertNull(getField(dateFormat, "_formatISO8601"));
        assertNull(getField(dateFormat, "_formatISO8601_z"));
        assertNull(getField(dateFormat, "_formatPlain"));
    }

    /**
     * Helper method to access private fields for verification purposes.
     */
    private Object getField(Object obj, String fieldName) throws Exception {
        Field field = StdDateFormat.class.getDeclaredField(fieldName);
        field.setAccessible(true);
        return field.get(obj);
    }
}
